                            <tr>                                <th>product_name</th>                                <th>allergens</th>                                <th>ingredients</th>                                <th>healthy_option</th>                                <th>recipe</th>                                <th>categories</th>                                <th>groups</th>                                <th>image_url</th>                            </tr>                            </thead>                            <tbody>                            <?php foreach ($sampleData as $row): ?>                                <tr>                                    <td><?php echo htmlspecialchars($row['product_name']); ?></td>                                    <td><?php echo htmlspecialchars($row['allergens']); ?></td>                                    <td><?php echo htmlspecialchars($row['ingredients']); ?></td>                                    <td><?php echo htmlspecialchars($row['healthy_option']); ?></td>                                    <td><?php echo htmlspecialchars($row['recipe']); ?></td>                                    <td><?php echo htmlspecialchars($row['categories']); ?></td>                                    <td><?php echo htmlspecialchars($row['groups']); ?></td>                                    <td><?php echo htmlspecialchars($row['image_url'] ?? ''); ?></td>                                </tr>                            <?php endforeach; ?>                            </tbody>                        </table>                    </div>                </div>            </div>            <!-- Export Tab -->            <div class="tab-pane fade" id="export" role="tabpanel" aria-labelledby="export-tab">                <div class="card">                    <div class="card-header">                        <h5 class="mb-0">Export Products</h5>                    </div>                    <div class="card-body">                        <div class="text-center py-4">                            <i class="bi bi-file-earmark-spreadsheet" style="font-size: 3rem; color: var(--primary-color);"></i>                            <h5 class="mt-3 mb-4">Export All Products to Excel</h5>                            <p>This will generate an Excel file containing all products in the database with their categories and groups.</p>                            <form action="product_import_export.php" method="POST">                                <input type="hidden" name="action" value="export">                                <button type="submit" class="btn btn-primary">                                    <i class="bi bi-download me-2"></i> Export Products                                </button>                            </form>                        </div>                    </div>                </div>                <!-- Export Instructions -->                <div class="card mt-4">                    <div class="card-header">                        <h5 class="mb-0">Export Options</h5>                    </div>                    <div class="card-body">                        <div class="row">                            <div class="col-md-6">                                <div class="card h-100">                                    <div class="card-body">                                        <h5><i class="bi bi-file-earmark-spreadsheet me-2"></i>Full Export</h5>                                        <p>Export all products with complete details including:</p>                                        <ul>                                            <li>Product names</li>                                            <li>Allergens</li>                                            <li>Ingredients</li>                                            <li>Health ratings</li>                                            <li>Recipes</li>                                            <li>Categories</li>                                            <li>Groups</li>                                        </ul>                                    </div>                                </div>                            </div>                            <div class="col-md-6">                                <div class="card h-100">                                    <div class="card-body">                                        <h5><i class="bi bi-lightbulb me-2"></i>Export Tips</h5>                                        <ul>                                            <li>Exported data can be used for backup purposes</li>                                            <li>You can edit the exported file and re-import with changes</li>                                            <li>Categories and groups are exported as comma-separated text</li>                                            <li>Images are not included in the export</li>                                        </ul>                                    </div>                                </div>                            </div>                        </div>                    </div>                </div>            </div>            <!-- Bulk Images Tab -->            <div class="tab-pane fade" id="images" role="tabpanel" aria-labelledby="images-tab">                <div class="card">                    <div class="card-header">                        <h5 class="mb-0">Upload Bulk Images</h5>                    </div>                    <div class="card-body">                        <div class="alert alert-info">                            <i class="bi bi-info-circle me-2"></i>                            Upload multiple product images at once. These images can be referenced in your Excel import file.                        </div>                        <form action="product_import_export.php" method="POST" enctype="multipart/form-data" id="bulk-images-form">                            <input type="hidden" name="action" value="upload_images">                            <div class="file-upload-container" onclick="document.getElementById('image_files').click();">                                <i class="bi bi-images upload-icon"></i>                                <h5>Click to select or drag & drop image files</h5>                                <p class="text-muted mb-1">Supported formats: .jpg, .jpeg, .png, .gif</p>                                <p class="text-muted">Max file size: 2MB per image</p>                                <input type="file" id="image_files" name="image_files[]" class="d-none" accept=".jpg,.jpeg,.png,.gif" multiple onchange="displayImageNames(this)">                                <div id="image-names" class="mt-3 text-primary"></div>                            </div>                            <div class="mt-4">                                <button type="submit" class="btn btn-primary" id="upload-images-btn" disabled>                                    <i class="bi bi-upload me-2"></i> Upload Images                                </button>                            </div>                        </form>                        <div class="mt-4">                            <h5><i class="bi bi-lightbulb me-2"></i>How to Use Bulk Images</h5>                            <ol>                                <li>Upload multiple images using the form above</li>                                <li>Images will be stored in the <code>uploads</code> directory</li>                                <li>When importing products via Excel, use the image filename in the <code>image_url</code> column</li>                                <li>Example: For an image named "chicken_salad.jpg", use <code>uploads/chicken_salad.jpg</code> in the Excel file</li>                            </ol>                        </div>                        <!-- Recently Uploaded Images -->                        <div class="mt-5" id="recent-images-container">                            <h5>Recently Uploaded Images</h5>                            <div class="row" id="recent-images">                                <!-- Images will be displayed here dynamically -->                            </div>                        </div>                    </div>                </div>            </div>        </div>    </div></div><!-- Template Download Form (hidden) --><form id="template-form" action="download_template.php" method="POST" class="d-none">    <input type="hidden" name="action" value="download_template"></form><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/js/bootstrap.bundle.min.js"></script><script>    // Display selected file name    function displayFileName(input) {        const fileName = input.files[0] ? input.files[0].name : '';        document.getElementById('file-name').textContent = fileName;        document.getElementById('preview-btn').disabled = !fileName;    }    // Download template function    function downloadTemplate() {        // Create data for Excel template        const templateData = [            ['product_name', 'allergens', 'ingredients', 'healthy_option', 'recipe', 'categories', 'groups'],            ['Chicken Salad', 'Eggs, Dairy', 'Chicken, Lettuce, Tomato, Cucumber, Dressing', 'Green', 'Mix all ingredients together', 'Lunch, Salads', 'Hot Food, Low Carb'],            ['Beef Burger', 'Gluten, Dairy', 'Beef patty, Bun, Cheese, Lettuce, Tomato', 'Amber', 'Grill beef patty, assemble burger', 'Lunch, Sandwiches', 'Hot Food, High Protein']        ];        // Convert to CSV        const csv = templateData.map(row => row.join(',')).join('\n');        // Create blob and download        const blob = new Blob([csv], { type: 'text/csv' });        const url = window.URL.createObjectURL(blob);        const a = document.createElement('a');        a.setAttribute('hidden', '');        a.setAttribute('href', url);        a.setAttribute('download', 'product_import_template.csv');        document.body.appendChild(a);        a.click();        document.body.removeChild(a);    }    // Drag and drop functionality    const dropZone = document.querySelector('.file-upload-container');    if (dropZone) {        ['dragenter', 'dragover', 'dragleave', 'drop'].forEach(eventName => {            dropZone.addEventListener(eventName, preventDefaults, false);        });        function preventDefaults(e) {            e.preventDefault();            e.stopPropagation();        }        ['dragenter', 'dragover'].forEach(eventName => {            dropZone.addEventListener(eventName, highlight, false);        });        ['dragleave', 'drop'].forEach(eventName => {            dropZone.addEventListener(eventName, unhighlight, false);        });        function highlight() {            dropZone.style.borderColor = 'var(--primary-color)';            dropZone.style.backgroundColor = '#f0f0f0';        }        function unhighlight() {            dropZone.style.borderColor = '#dee2e6';            dropZone.style.backgroundColor = '#fff';        }        dropZone.addEventListener('drop', handleDrop, false);        function handleDrop(e) {            const dt = e.dataTransfer;            const files = dt.files;            const fileInput = document.getElementById('excel_file');            fileInput.files = files;            displayFileName(fileInput);        }    }    // Display selected image filenames    function displayImageNames(input) {        const fileNames = [];        const filesContainer = document.getElementById('image-names');        filesContainer.innerHTML = '';        if (input.files && input.files.length > 0) {            for (let i = 0; i < input.files.length; i++) {                fileNames.push(input.files[i].name);            }            const filesList = document.createElement('ul');            filesList.className = 'list-group';            fileNames.forEach(name => {                const listItem = document.createElement('li');                listItem.className = 'list-group-item small';                listItem.textContent = name;                filesList.appendChild(listItem);            });            filesContainer.appendChild(filesList);            document.getElementById('upload-images-btn').disabled = false;        } else {            document.getElementById('upload-images-btn').disabled = true;        }    }    // Drag and drop for images    const imagesDropZone = document.querySelector('#bulk-images-form .file-upload-container');    if (imagesDropZone) {        ['dragenter', 'dragover', 'dragleave', 'drop'].forEach(eventName => {            imagesDropZone.addEventListener(eventName, preventDefaults, false);        });        ['dragenter', 'dragover'].forEach(eventName => {            imagesDropZone.addEventListener(eventName, highlight, false);        });        ['dragleave', 'drop'].forEach(eventName => {            imagesDropZone.addEventListener(eventName, unhighlight, false);        });        imagesDropZone.addEventListener('drop', handleImageDrop, false);        function handleImageDrop(e) {            const dt = e.dataTransfer;            const files = dt.files;            const fileInput = document.getElementById('image_files');            fileInput.files = files;            displayImageNames(fileInput);        }    }    // Load recently uploaded images    function loadRecentImages() {        const recentImagesContainer = document.getElementById('recent-images');        if (!recentImagesContainer) return;        // Clear container        recentImagesContainer.innerHTML = '';        // Make AJAX request to get recent images        fetch('get_recent_images.php')            .then(response => response.json())            .then(data => {                if (data.images && data.images.length > 0) {                    data.images.forEach(image => {                        const col = document.createElement('div');                        col.className = 'col-md-2 col-sm-4 col-6 mb-3';                        const card = document.createElement('div');                        card.className = 'card h-100';                        const img = document.createElement('img');                        img.src = image.path;                        img.className = 'card-img-top';                        img.alt = image.name;                        img.style.height = '100px';                        img.style.objectFit = 'cover';                        const cardBody = document.createElement('div');                        cardBody.className = 'card-body p-2';                        const cardTitle = document.createElement('p');                        cardTitle.className = 'card-text small text-truncate mb-0';                        cardTitle.title = image.name;                        cardTitle.textContent = image.name;                        const cardPath = document.createElement('p');                        cardPath.className = 'card-text small text-muted text-truncate mb-0';                        cardPath.title = image.path;                        cardPath.textContent = image.path;                        cardBody.appendChild(cardTitle);                        cardBody.appendChild(cardPath);                        card.appendChild(img);                        card.appendChild(cardBody);                        col.appendChild(card);                        recentImagesContainer.appendChild(col);                    });                } else {                    recentImagesContainer.innerHTML = '<div class="col-12"><p class="text-muted">No images uploaded yet.</p></div>';                }            })            .catch(error => {                console.error('Error loading recent images:', error);                recentImagesContainer.innerHTML = '<div class="col-12"><p class="text-danger">Error loading images.</p></div>';            });    }    // Activate tab based on URL parameter    function activateTabFromUrl() {        const urlParams = new URLSearchParams(window.location.search);        const tab = urlParams.get('tab');        if (tab) {            const tabElement = document.querySelector(`#${tab}-tab`);            if (tabElement) {                const tabInstance = new bootstrap.Tab(tabElement);                tabInstance.show();            }        }    }    // Responsive sidebar toggle    document.addEventListener('DOMContentLoaded', function() {        // Activate proper tab if specified in URL        activateTabFromUrl();        // Load recent images if on images tab        if (document.querySelector('#images.active')) {            loadRecentImages();        }        // Handle tab change to load images        document.querySelector('#images-tab').addEventListener('shown.bs.tab', function (e) {            loadRecentImages();        });        const mediaQuery = window.matchMedia('(max-width: 768px)');        function handleScreenChange(e) {            if (e.matches) {                document.querySelector('.sidebar').classList.add('collapsed');                document.querySelector('.main-content').classList.add('expanded');            } else {                document.querySelector('.sidebar').classList.remove('collapsed');                document.querySelector('.main-content').classList.remove('expanded');            }        }        mediaQuery.addListener(handleScreenChange);        handleScreenChange(mediaQuery);    });</script></body></html>